    Ltac fin_regs FIN HR' :=
      eapply (FIN _ (or_intror I));
      [ let Q := fresh in rreg HR' 2%bv Q; exact Q
      | let Q := fresh in rreg HR' 3%bv Q; exact Q
      | let Q := fresh in rreg HR' 4%bv Q; exact Q
      | exact (syms_id_sound _ _ _ _ [20; 21; 22; 23; 24; 25; 26; 27]%bv HR' eq_refl)
      | let Q := fresh in rreg HR' 8%bv Q; exact Q
      | let Q := fresh in rreg HR' 9%bv Q; exact Q
      | let Q := fresh in rreg HR' 18%bv Q; exact Q
      | let Q := fresh in rreg HR' 10%bv Q; first [exact Q | rewrite Q; f_equal; lia]
      | let Q := fresh in rreg HR' 12%bv Q; first [exact Q | rewrite Q; reflexivity | rewrite Q; f_equal; lia]
      | let Q := fresh in rreg HR' 11%bv Q; first [exact Q | rewrite Q; rewrite ?w_remu by lia; f_equal; lia]
      | ].

