    Lemma phaseD : forall A1 M1 A2 M3 model2 R3 p,
      rst (FC p) (opsB p) p A2 M3 model2 R3 -> getr R3 8%bv = Z_to_bv 64 p ->
      umapx MI 24 (nval24 SEGS) A1 M1 obj bl bc ents ->
      agree_on M1 M3 (obj + 16) 24 ->
      (forall q k v, In (q, (k, v)) ents -> agree_on M1 M3 q 24 /\ In (q, 24) (live MI A2)) ->
      (forall i, 0 <= i < n -> cell8 SEGS M3 (p + 8 * i) 0) ->
      (ents = [] -> forall R4, base_ok R4 -> srealizes SEGS (cfg fx R4 EXIT_PC M3 model2) K) ->
      (forall e S M4 R4 (pc : Z), ents = e :: S -> (pc = EXIT_PC /\ S = [] \/ pc = LOOP_PC /\ S <> []) ->
          lst p M1 [e] S (fun i => if i =? hh e then sent else 0) A2 M4 R4 ->
          (forall a : word, ~ Wloop p (bv_unsigned a) -> M4 a = M3 a) -> (forall a : word, M3 a <> None -> M4 a <> None) ->
          ainv MI A2 M4 model2 ->
          srealizes SEGS (cfg fx R4 pc M4 model2) K) ->
      srealizes SEGS (cfg fx R3 MSRET M3 model2) K.
Proof using AC L MI ST NEW_STACK DEL_STACK NEW_STACK_nn DEL_STACK_nn fx A0 s R0 M0 model0 sp ret obj bl bc ents K CB U0 Hlast ASP CONT.
